import React from 'react'
import img from '../../assets/image/img.png'
import './index.scss'

export default function IconAndText(props) {
  const { text, show ,icon , onClick} = props
  return (
    <div className='iconContent cursor' onClick={onClick}>
      {/* <img src={img} alt="" /> */}
      {icon}
      <div className='iconInfo' style={{ opacity: show ? 1 : 0 }}>{text}</div>
    </div>
  )
}
