import React, { useContext, useEffect, useState } from 'react'
import IconAndText from '../iconAndText/IconAndText'
import IconAndTextAndSelect from '../iconAndTextAndSelect/IconAndTextAndSelect'
import Drawer from '../Drawer/Drawer'
import { Col, InputNumber, Row, Slider } from 'antd'
import { pageContext } from '../../page/test/Test'
import { SelectionHelper } from '../selectBox/SelectBox'
import { withTranslation } from 'react-i18next'

// const selectHelper = new SelectionHelper(document.body, 'selectBox');

function SecondTitle(props) {
    const { t, i18n } = props;

    const pageInfo = useContext(pageContext);
    console.log('SecondTitle')
    const [show, setShow] = useState(false)
    const [setshow, setSetshow] = useState(false)
    const { settingValue, setSettingValue, selectHelper } = pageInfo
    const onChange = (newValue, type) => {
        console.log(newValue, type, settingValue)
        let obj = { ...settingValue }
        obj[type] = newValue
        localStorage.setItem('setValueData', JSON.stringify(obj))
        setSettingValue(obj);
    };

    const setType = [
        {
            title: t('blur'),
            type: 'gauss',
            max : 4  ,
            min : 1,
            step : 0.1
        },
        {
            title: t('colorAdj'),
            type: 'color',
            max : 1000  ,
            min : 1,
            step : 10
        },
        {
            title: t('denoise'),
            type: 'filter',
            max : 20  ,
            min : 1,
            step : 1
        },
        {
            title: t('heightAdj'),
            type: 'height',
            max : 4  ,
            min : 1,
            step : 0.1
        },
        {
            title: t('continuity'),
            type: 'coherent',
            max : 10  ,
            min : 1,
            step : 1
        },
    ]


    const [onSelect, setOnSelect] = useState(false)


    const selectClick = () => {
        setOnSelect(!onSelect)
        // if (!onSelect) {
        //     selectHelper.isShiftPressed = true
        // }else{
        //     selectHelper.isShiftPressed = false
        // }
        pageInfo?.brushInstance.startBrush();
    }

    useEffect(() => {


    }, [])
    // const brush = useContext(BrushContext);

    const wsDataZero = () => {
        pageInfo.changeWsLocalData()
    }

    return (

        <>
            <Drawer zindex={3} show={setshow} title={t('adjust')} setShow={setSetshow}>
                <div className="setContent">
                    {/* <div className="setItem">
                        <Row align='middle'>
                            <Col span={4} >高斯模糊</Col>
                            <Col span={12}>
                                <Slider
                                    min={1}
                                    max={20}
                                    onChange={(value) => {
                                        onChange(value, 'gauss')
                                    }}
                                    value={typeof settingValue.gauss === 'number' ? settingValue.gauss : 0}
                                />
                            </Col>
                            <Col span={4}>
                                <InputNumber
                                    min={1}
                                    max={20}
                                    style={{ margin: '0 16px' }}
                                    value={typeof settingValue.gauss === 'number' ? settingValue.gauss : 0}
                                    onChange={(value) => {
                                        onChange(value, 'gauss')
                                    }}
                                />
                            </Col>
                        </Row>
                    </div> */}
                    {
                        setType.map((a, index) => {
                            return (
                                <div className="setItem">
                                    <Row align='middle'>
                                        <Col span={4} >{a.title}</Col>
                                        <Col span={12}>
                                            <Slider
                                                min={a.min}
                                                max={a.max}
                                                step={a.step}
                                                onChange={(value) => {
                                                    onChange(value, a.type)
                                                }}
                                                value={typeof settingValue[a.type] === 'number' ? settingValue[a.type] : 0}
                                            />
                                        </Col>
                                        <Col span={4}>
                                            <InputNumber
                                                min={a.min}
                                                max={a.max}
                                                style={{ margin: '0 16px' }}
                                                value={typeof settingValue[a.type] === 'number' ? settingValue[a.type] : 0}
                                                onChange={(value) => {
                                                    onChange(value, a.type)
                                                }}
                                            />
                                        </Col>
                                    </Row>
                                </div>
                            )
                        })
                    }
                </div>
            </Drawer>
            <div className="secondTitle">
                <div className="secondTitleContent" style={{ height: show ? `calc(27px + 2.7rem)` : 'calc(27px + 0.6rem)' }}
                    onMouseOver={() => {
                        setShow(true)
                    }}
                    onMouseOut={() => {
                        setShow(false)
                    }}
                >
                    {/* <IconAndText text='画布翻转' /> */}
                    <IconAndTextAndSelect text={t('flip')} show={show} options={[{
                        label: t('flipV'), value: 'up'
                    }, {
                        label: t('flipH'), value: 'left'
                    },
                    ]}
                        icon={<i className='iconfont fs26'>&#xe60c;</i>}
                    />
                    <IconAndText text={t('zeroPre')} show={show} onClick={wsDataZero} icon={<i className='iconfont fs26'>&#xe604;</i>} />
                    <IconAndText text={t('select')} onClick={() => { selectClick() }} show={show} icon={<i style={{ color: onSelect ? 'blue' : '#B4C0CA' }} className='iconfont fs26'>&#xe60e;</i>} />
                    <IconAndText text={t('ruler')} show={show} icon={<i className='iconfont fs26'>&#xe610;</i>} />
                    <IconAndText onClick={() => { setSetshow(!setshow) }} text={t('adjust')} show={show} icon={<i className='iconfont fs26'>&#xe60d;</i>} />
                    <IconAndText text={t('upload')} show={show} icon={<i className='iconfont fs26'>&#xe609;</i>} />
                </div>
            </div>
        </>
    )
}

export default withTranslation('translation')(SecondTitle)
