import React, { useContext } from 'react'
import './index.scss'
import { pageContext } from '../../page/test/Test';
import { withTranslation } from 'react-i18next';

function EquipStatus(props) {

    const { t, i18n } = props;

    const portMap = {
        'car': [{ label: t('back'), value: 'back' }, { label: t('sit'), value: 'sit' }]
    }

    const { fileName } = props
    const pageInfo = useContext(pageContext);
    console.log('EquipStatus')

    return (
        <div className='equipsStatusContent'>
            {
                portMap[fileName].map((a, index) => {
                    return (
                        <div className='equipStatusContent'>
                            <div className='equipName'>{a.label}</div> <div className={pageInfo.equipStatus[a.value] ? 'equipOfflineStatus' : 'equipOnlineStatus'}></div>
                        </div>
                    )
                })
            }
        </div>
    )
}

export default withTranslation('translation')(EquipStatus);
