import React, { useState } from 'react'
import './index.scss'
const dataMap = [
  {
    label: '汽车',
    value: 'car'
  },
  {
    label: '床垫',
    value: 'bed'
  },
]
export default function Select(props) {

  const { options, defaultValue , onChange } = props
  console.log(options)
  const [show, setShow] = useState(false)
  const [value, setValue] = useState(defaultValue)

  console.log(value ,defaultValue, 'select')
  return (
    <>
      <div
        onMouseOver={() => {
          setShow(true)
        }}
        onMouseOut={() => {
          setShow(false)
        }}
        className="systemSelect cursor" style={{ width: "5.5rem" }}>
        {value || defaultValue}
        <div className="dropDown" style={{ opacity: show ? 1 : 0 }}>
          <div className='dropDownAni' style={{ left: show ? 0 : '-100%' }}></div>
          {options.map((a, index) => {
            return (
              <div className='dropItem' onClick={() => {
                setValue(a.label)
                setShow(false)
                onChange(a.value)
              }}>
                {a.label}
              </div>
            )
          })}
        </div>
      </div>
    </>
  )
}
