export default function ViewSetting(props) {
    const pageInfo = useContext(pageContext);
    console.log('ViewSetting')
    const { setDisplay, display } = pageInfo

    useEffect(() => {
        props.three?.current?.changePointRotation(xvalue)
    }, [])

    const threeViewChange = () => {
        console.log(111)
        xvalue++;
        if (xvalue > 2) {
            xvalue = 0
        }
        props.three?.current?.changePointRotation(xvalue)
        
    }

    return (
        <div className='viewSetContent'>
            <div className="threeViewSizeAdjust">
                <i className='iconfont reduce cursor'>&#xe632;</i>
                <Input />
                <i className='iconfont add cursor'>&#xe631;</i>
            </div>
            <i className='iconfont viewAdjust cursor' onClick={threeViewChange}>&#xe606;</i>
            <i className='iconfont viewAdjust cursor' onClick={() => setDisplay(!display)}>&#xe607;</i>
        </div>
    )
}
