import React, { useState } from 'react'
import './index.scss'

export default function Drawer(props) {
    const { show, title, setShow, children, asideClose, zindex,close } = props
    console.log(zindex, 'props')
    return (
        <div className='drawerContent' style={{ right: show ? 0 : 'calc(-18% - 5px)', zIndex: zindex ? zindex * 100 : 100 }}>
            {asideClose ? <div className='asideClose' onClick={() => { setShow(!show) }}>
                <i className='iconfont'>&#xe621;</i>
            </div> : ''}
            <div className="drawerTitle">
                <div className="titleInfo">{title}</div>
                <div className="closeDrawer cursor" onClick={() => {
                    if(close){
                        close()
                    }
                    setShow(false)
                }}>
                    <i className='iconfont'>&#xe625;</i>
                </div>
            </div>

            <div className="drawerInside">
                {children}
            </div>
        </div>
    )
}
